  \node[below] at (1,-0.06) {\(1\)};
  \node[below] at (1.414,-0.06) {\(\sqrt2\)};
  \node[above] at (1.05,0.15) {\(x^2<2\)};
  \node[above] at (1.58,0.7) {upper bounds};
